import {adminGuideHtml} from '/admin-guide.js';
const $=s=>document.querySelector(s);
let lang=localStorage.getItem('production-language')==='en'?'en':'zh',page='overview',csrf='',status={},data={},admin=null;
const texts={en:{'正式后台开发版':'Production workspace · development','本地开发环境 · 实际收款与广播未启用':'Local development · deposits and broadcast are disabled','概览':'Overview','正式订单':'Orders','出款审核':'Payout approvals','网络配置':'Network settings','操作记录':'Activity','退出登录':'Sign out','刷新':'Refresh','管理员账号':'Administrator name','密码':'Password','重复密码':'Repeat password','登录':'Sign in','初始化管理员':'Create administrator','设置首个管理员账号，密码至少12个字符。':'Create the first administrator account. Use at least 12 characters for the password.','输入管理员账号和密码。':'Enter your administrator name and password.','创建账号并登录':'Create account and sign in','订单总数':'Orders','待审核出款':'Pending approvals','已审核待签名':'Approved · awaiting signing','数据库':'Database','创建正式订单':'Create order','订单编号':'Order ID','类型':'Type','本金':'Principal','状态':'Status','操作':'Action','查看':'View','暂无订单':'No orders yet','暂无出款申请':'No payout requests yet','金额':'Amount','收款地址':'Recipient','审核':'Review','审核申请':'Review payout request','申请编号':'Request ID','手续费':'Fee','交易约定':'Transaction terms','审核理由':'Review note','通过审核':'Approve','拒绝':'Reject','审核不会直接转账，请在独立测试签名页核对和广播。':'Approval does not send funds. Review and explicitly broadcast through the separate test signer.','商品／服务':'Goods / services','USDT 买卖':'USDT trade','买家数字 ID':'Buyer Telegram ID','卖家数字 ID':'Seller Telegram ID','买家钱包地址':'Buyer wallet address','卖家钱包地址':'Seller wallet address','交易本金':'Principal','创建':'Create','取消':'Cancel','网络':'Network','BNB 测试网（97）':'BNB testnet (97)','BNB 主网（56）':'BNB mainnet (56)','代币合约':'Token contract','保存网络配置':'Save network settings','测试网需填写实际部署的18位测试代币合约。配置收款分支后，网络与合约锁定；主网收款仍未启用。':'Testnet requires a deployed 18-decimal test token. Importing the wallet root locks chain and token identity. Mainnet deposits remain disabled.','未配置':'Not configured','时间':'Time','操作者':'Actor','事件':'Event','记录对象':'Target','无记录':'No records','订单详情':'Order details','双方确认':'Party acceptances','已分配收款地址':'Allocated deposit address','尚未分配，请勿转账':'Not allocated. Do not transfer funds.','创建后等待真实双方确认，后台不会代替用户确认。':'The order awaits actual party acceptance. Administrators cannot impersonate either party.','保存成功':'Saved','订单已创建':'Order created','密码至少12个字符，且两次输入必须一致':'Use at least 12 characters and matching passwords','请先配置代币合约':'Configure the token contract first','已通过审核，等待签名服务':'Approved; awaiting signing service','已拒绝并转人工处理':'Rejected; manual review required','金额采用18位精度；创建后默认费用为最低5或本金5%中的较高者。':'Amounts use 18 decimals. The fee is the greater of 5 tokens or 5% of principal.','API/签名接入状态':'Integration status','正式钱包、链监听、Telegram身份和签名服务待接入。本页面已有登录、订单登记和出款审核逻辑。':'Wallet allocation, monitoring, Telegram identity and signing remain to be connected. Login, order registration and payout review logic are available.','恢复测试需要独立测试数据，不在当前正式数据中注入假入金。':'Use isolated fixtures for recovery tests. Fake deposits are not injected into this workspace.'}};
const t=s=>lang==='en'?(texts.en[s]??s):s;
Object.assign(texts.en,{'入金总额':'Required deposit','入金记录':'Deposits','停止后台':'Stop service','服务已停止':'Service stopped','确认停止后台':'Confirm service shutdown','输入 STOP':'Type STOP','账号或密码错误，连续失败会暂时锁定':'Incorrect name or password. Repeated failures temporarily lock login.','请先登录':'Sign in first','请求会话已失效，请刷新':'Request session expired. Refresh the page.','请先在网络配置中填写代币合约':'Configure the token contract first.','双方必须是不同账号':'The parties must use different accounts.','请填写交易约定':'Enter transaction terms.','请填写审核理由':'Enter a review note.','没有出款审核权限':'Payout approval permission required.','审批记录已变化，请刷新':'The approval record changed. Refresh it.','托管余额与分配方案不一致':'Escrow balance does not match the allocation.','请求编号已用于不同内容':'Request ID was already used for different content.','订单不存在':'Order not found.','无效 Telegram 数字 ID':'Invalid numeric Telegram ID.','操作未成功，请刷新核对':'Operation failed. Refresh and verify the current state.'});
const states={AWAITING_ACCEPTANCE:['待双方确认','Awaiting party acceptance'],AWAITING_DEPOSIT:['待入金','Awaiting deposit'],FUNDED:['已入金','Funded'],AWAITING_CONFIRMATION:['待验收','Awaiting confirmation'],PENDING_APPROVAL:['待审核','Pending approval'],APPROVED:['已审核待签名','Approved · awaiting signing'],TIMED_OUT:['超时暂停','Timed out'],MANUAL_REVIEW:['人工待处理','Manual review'],PENDING:['待审核','Pending'],REJECTED:['已拒绝','Rejected'],BLOCKED:['已暂停','Blocked'],COMPLETED:['已完成','Completed']};
const state=s=>states[s]?.[lang==='en'?1:0]??s;
Object.assign(states,{running:['运行中','Running'],stopped:['已停止','Stopped'],starting:['连接中','Connecting'],stopping:['停止中','Stopping'],configuring:['保存中','Saving'],error:['连接失败','Connection failed']});
Object.assign(states,{PREPARED:['已准备交易','Prepared'],SIGNED:['签名已核验','Signature validated'],BROADCAST:['已广播待最终确认','Broadcast; awaiting finality'],CONFIRMED:['已最终确认','Finalized'],REVERTED:['链上失败待处理','Reverted; manual handling'],PAID:['已出款','Paid']});
Object.assign(states,{REFUND_REQUESTED:['待对方确认退款','Awaiting refund agreement'],DISPUTED:['争议中','Disputed'],REFUNDED:['已退款','Refunded'],ARBITRATED:['裁决出款已完成','Arbitration payout completed'],OPEN:['待对方回应','Awaiting response'],AGREED:['已协商同意','Agreed'],RESOLVED:['已裁决待审核','Resolved; awaiting review']});
Object.assign(texts.en,{'退款与争议':'Refunds and disputes','案件编号':'Case ID','案件类型':'Case type','案件说明':'Case reason','退款申请':'Refund request','争议':'Dispute','查看案件':'View case','暂无案件':'No cases','案件记录':'Case history','裁决方案':'Decision','全部退买家（包含手续费）':'Full refund to buyer (including fee)','本金给卖家（保留原手续费）':'Principal to seller (retain original fee)','裁决理由':'Decision reason','提交裁决并生成待审核出款':'Submit decision for payout review','输入 RESOLVE':'Type RESOLVE','裁决不会直接转账，还需出款审核与独立签名。':'A decision does not transfer funds. Payout review and separate signing are still required.','案件已提交出款审核':'Decision submitted for payout review','请准确输入 RESOLVE':'Type RESOLVE exactly.','已有签名交易，须先核对原交易，不能另行退款或裁决':'A signed transaction exists. Reconcile it before creating another refund or decision.','没有裁决权限':'Decision permission required.','案件或订单状态已变化':'Case or order state changed.','无效裁决方案':'Invalid decision.'});
Object.assign(texts.en,{'正式 Telegram 机器人':'Production Telegram bot','Token 已保存，页面不会回显。':'Token saved; it is never returned to the page.','尚未保存 Token。':'No token is configured.','保存 Token':'Save token','启动正式机器人':'Start production bot','停止机器人':'Stop bot','邀请交易方':'Invite parties','交易方操作记录':'Party activity','测试网已接入身份、入金监听与独立签名出款；主网真实资金仍未开放。':'Testnet identity, deposit monitoring and separate signing/payout are connected. Mainnet funds remain disabled.','请只在本机填写 Token。若使用旧模拟版的同一个机器人，先停止模拟机器人。':'Enter the token locally only. Stop the simulation bot first if it uses the same bot.','后台需重启加载 Telegram 接口':'Restart the service to load Telegram integration.','确认启动正式机器人':'Confirm production bot startup','输入 START':'Type START','启用后此机器人使用正式商品订单，旧模拟订单不在本入口展示。实际资金功能仍未启用。':'This bot will use production goods orders. Simulation orders are not shown here. Actual funds are still disabled.','正式机器人已启动':'Production bot started','正式机器人已停止':'Production bot stopped','同一机器人仍在模拟版运行，请先停止模拟机器人':'The same bot is still running in simulation. Stop it first.','请先停止正式机器人再修改 Token':'Stop the production bot before changing its token.','请填写有效的机器人 Token':'Enter a valid bot token.','正式机器人连接失败，请检查本机配置和网络':'Production bot connection failed. Check local settings and network.'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount=s=>{const n=BigInt(s??'0'),scale=10n**18n,part=(n%scale).toString().padStart(18,'0').replace(/0+$/,'');return (n/scale).toString()+(part?'.'+part:'');};
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok){if(r.status===401&&!['/api/login'].includes(path)){admin=null;await loadAuth();}throw Error(t(d.error??'Request failed'));}return d;}
function chrome(){document.documentElement.lang=lang==='en'?'en':'zh-CN';$('#language').value=lang;$('#subtitle').textContent=t('正式后台开发版');$('#notice').textContent=t('本地开发环境 · 实际收款与广播未启用');$('#logout').textContent=t('退出登录');$('#refresh').textContent=t('刷新');for(const [selector,label] of [['#username-label','管理员账号'],['#password-label','密码'],['#repeat-label','重复密码']])$(selector).firstChild.textContent=t(label);for(const button of $('#nav').children)button.textContent=t({overview:'概览',orders:'正式订单',approvals:'出款审核',settings:'网络配置',cases:'退款与争议',audit:'操作记录',guide:'管理员指南'}[button.dataset.page]);}
async function loadAuth(){status=await api('/api/status');$('#workspace').hidden=true;$('#auth').hidden=false;$('#logout').hidden=true;$('#shutdown').hidden=true;$('#identity').textContent='';const setup=!status.initialized;$('#auth-title').textContent=t(setup?'初始化管理员':'登录');$('#auth-description').textContent=t(setup?'设置首个管理员账号，密码至少12个字符。':'输入管理员账号和密码。');$('#auth-submit').textContent=t(setup?'创建账号并登录':'登录');$('#repeat-label').hidden=!setup;$('#repeat-label input').required=setup;$('#password-label input').minLength=setup?12:1;}
async function refresh(){data=await api('/api/overview');render();}
function table(headers,rows,empty){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${t(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">${t(empty)}</td></tr>`}</tbody></table></div>`;}
function render(){if(!admin)return;$('#identity').textContent=`${admin.username} · ${admin.role}`;$('#shutdown').hidden=admin.role!=='OWNER';$('#shutdown').textContent=t('停止后台');$('#page-title').textContent=t({overview:'概览',orders:'正式订单',approvals:'出款审核',settings:'网络配置',cases:'退款与争议',audit:'操作记录',guide:'管理员指南'}[page]);for(const b of $('#nav').children)b.classList.toggle('active',b.dataset.page===page);
if(page==='overview')$('#content').innerHTML=`<div class="cards">${[['订单总数',data.orders.length],['待审核出款',data.approvals.filter(r=>r.status==='PENDING').length],['已审核待签名',data.approvals.filter(r=>r.status==='APPROVED').length],['数据库',data.engine]].map(([k,v])=>`<div class="card"><span>${t(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="panel"><h2>${t('API/签名接入状态')}</h2><p>${t(data.wallet?'测试网已接入身份、入金监听与独立签名出款；主网真实资金仍未开放。':'后台需重启加载钱包接口')}</p><small>${t('恢复测试需要独立测试数据，不在当前正式数据中注入假入金。')}</small></div>`;
if(page==='orders')$('#content').innerHTML=`<div class="panel"><div class="toolbar"><span>${data.orders.length} ${t('正式订单')}</span><button id="create" class="primary">＋ ${t('创建正式订单')}</button></div>${table(['订单编号','类型','本金','状态','操作'],data.orders.map(o=>`<tr><td class="mono">${esc(o.id)}</td><td>${t(o.kind==='PRODUCT'?'商品／服务':'USDT 买卖')}</td><td>${amount(o.principal)} USDT</td><td><span class="badge">${esc(state(o.state))}</span></td><td><button data-detail="${esc(o.id)}">${t('查看')}</button></td></tr>`),'暂无订单')}</div>`;
if(page==='approvals')$('#content').innerHTML=`<div class="panel">${table(['申请编号','金额','状态','操作'],data.approvals.map(r=>`<tr><td class="mono">${esc(r.id)}<br><small>${esc(r.order_id)}</small></td><td>${amount(r.allocations.reduce((n,a)=>n+BigInt(a.amount),0n).toString())} USDT</td><td><span class="badge">${esc(state(r.status))}</span></td><td><button data-review="${esc(r.id)}">${t(r.status==='PENDING'?'审核':'查看')}</button></td></tr>`),'暂无出款申请')}</div>`;
if(page==='settings')$('#content').innerHTML=`<div class="panel"><form id="network-form"><div class="grid"><label>${t('网络')}<select name="chainId"><option value="97">${t('BNB 测试网（97）')}</option><option value="56">${t('BNB 主网（56）')}</option></select></label><label>${t('代币合约')}<input name="tokenContract" class="mono" value="${esc(data.settings.token_contract??'')}" required pattern="0x[0-9a-fA-F]{40}"></label></div><p>${t('测试网需填写实际部署的18位测试代币合约。配置收款分支后，网络与合约锁定；主网收款仍未启用。')}</p><div><button class="primary" ${admin.role!=='OWNER'?'disabled':''}>${t('保存网络配置')}</button></div></form></div>`;
if(page==='settings')$('#content').insertAdjacentHTML('beforeend',botSettings());
if(page==='cases'){
  $('#content').innerHTML=`<div class="panel">${table(['案件编号','案件类型','状态','案件说明','操作'],(data.cases??[]).map(c=>`<tr><td class="mono">${esc(c.id)}<br>${esc(c.order_id)}</td><td>${t(c.kind==='REFUND'?'退款申请':'争议')}</td><td>${esc(state(c.status))}</td><td>${esc(c.reason)}</td><td><button data-case="${esc(c.id)}">${t('查看案件')}</button></td></tr>`),'暂无案件')}</div>`;
  for(const button of document.querySelectorAll('[data-case]'))button.onclick=()=>caseDetail(button.dataset.case).catch(e=>toast(e.message));
}
if(page==='approvals')$('#content').insertAdjacentHTML('beforeend',`<div class="panel"><h2>${lang==='en'?'Separate testnet signer':'独立测试网签名与出款'}</h2><p>${lang==='en'?'Only approved goods orders can prepare a transaction. Signing and broadcast require separate confirmation. Mainnet is disabled.':'仅已审核通过的商品订单可准备交易，签名与广播分别确认；主网未开放。'}</p><a href="http://127.0.0.1:8783/#payout-panel" target="_blank" rel="noopener noreferrer">${lang==='en'?'Open testnet signer':'打开测试网签名页面'}</a>${table(['申请编号','状态','记录对象'],(data.payoutTransactions??[]).map(p=>`<tr><td class="mono">${esc(p.request_id)}</td><td>${esc(state(p.status))}</td><td class="mono">${esc(p.tx_hash??p.last_error??'—')}</td></tr>`),'无记录')}</div>`);
if(page==='settings')$('#content').insertAdjacentHTML('beforeend',walletSettings());
if(page==='guide')$('#content').innerHTML=adminGuideHtml(lang);
if(page==='settings'){$('#content').insertAdjacentHTML('afterbegin','<div class="panel" id="automation-panel"></div><div class="panel" id="platform-panel"></div><div class="panel" id="custody-panel"></div><div class="panel" id="revenue-panel"></div><div class="panel" id="welcome-image-panel"></div><div class="panel" id="admins-panel"></div>');if(admin.role==='OWNER')automationPanel().catch(e=>toast(e.message));else $('#automation-panel').remove();platformPanel().catch(e=>toast(e.message));welcomeImagePanel().catch(e=>toast(e.message));custodyPanel().catch(e=>toast(e.message));if(admin.role==='OWNER')revenuePanel().catch(e=>toast(e.message));else $('#revenue-panel').remove();adminsPanel().catch(e=>toast(e.message));$('#content').insertAdjacentHTML('beforeend','<div class="panel" id="alerts-panel"></div><div class="panel" id="allowlist-panel"></div><div class="panel" id="timeouts-panel"></div>');alertsPanel().catch(e=>toast(e.message));allowlistPanel().catch(e=>toast(e.message));timeoutSettings().catch(e=>toast(e.message));}
if(page==='settings'&&admin.role==='OWNER'){$('#content').insertAdjacentHTML('beforeend','<div class="panel" id="backup-panel"></div>');backupPanel().catch(e=>{const p=$('#backup-panel');if(p)p.innerHTML=`<h2>${t('加密备份与恢复校验')}</h2><p>${esc(t(e.message))}</p>`;});}
$('#notice').textContent=data.network?.chainId===56?(lang==='en'?`MAINNET · REAL USDT · max ${amount(data.network.maxOrder)} USDT per order · max ${amount(data.network.maxCustody)} USDT in open orders · fee ${data.network.feeBps/100}% (min ${data.network.feeMin})`:`主网 · 真实 USDT · 单笔上限 ${amount(data.network.maxOrder)} USDT · 进行中订单托管上限 ${amount(data.network.maxCustody)} USDT · 手续费 ${data.network.feeBps/100}%（最低 ${data.network.feeMin}）`):data.wallet?.state==='running'?t('仅 BNB 测试网 · 禁止发送主网 USDT · 测试出款须独立签名与确认'):t('本地开发环境 · 实际收款与广播未启用');document.body.classList.toggle('mainnet',data.network?.chainId===56);
if(page==='audit')$('#content').innerHTML=`<div class="panel">${table(['时间','操作者','事件','记录对象'],data.audit.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString(lang==='en'?'en-US':'zh-CN'))}</td><td>${esc(a.username??'system')}</td><td class="mono">${esc(a.action)}</td><td class="mono">${esc(a.target_id??'—')}</td></tr>`),'无记录')}</div>`;
if(page==='audit')$('#content').insertAdjacentHTML('beforeend',`<div class="panel"><h2>${t('交易方操作记录')}</h2>${table(['时间','操作者','事件','记录对象'],(data.partyActions??[]).map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString(lang==='en'?'en-US':'zh-CN'))}</td><td class="mono">${esc(a.user_id)}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.order_id)}</td></tr>`),'无记录')}</div>`);
$('#create')?.addEventListener('click',create);for(const button of document.querySelectorAll('[data-detail]'))button.onclick=()=>detail(button.dataset.detail).catch(e=>toast(e.message));for(const button of document.querySelectorAll('[data-review]'))button.onclick=()=>review(button.dataset.review);
const network=$('#network-form');if(network){network.elements.chainId.value=data.settings.chain_id;network.onsubmit=async e=>{e.preventDefault();try{await api('/api/settings',Object.fromEntries(new FormData(network)));toast(t('保存成功'));await refresh();}catch(e){toast(e.message);}};}}
function botSettings(){if(!data.bot)return `<div class="panel"><p>${t('后台需重启加载 Telegram 接口')}</p></div>`;const b=data.bot,owner=admin.role==='OWNER',active=['running','starting','stopping','configuring'].includes(b.state);queueMicrotask(()=>{const form=$('#bot-form');if(form)form.onsubmit=async e=>{e.preventDefault();const token=new FormData(form).get('token');const button=form.querySelector('button');button.disabled=true;try{await api('/api/bot/configure',{token});form.reset();toast(t('保存成功'));await refresh();}catch(e){toast(e.message);}finally{button.disabled=false;}};$('#bot-start')?.addEventListener('click',startBot);$('#bot-stop')?.addEventListener('click',async()=>{try{await api('/api/bot/stop',{});toast(t('正式机器人已停止'));await refresh();}catch(e){toast(e.message);}});});return `<div class="panel"><h2>${t('正式 Telegram 机器人')}</h2><p><span class="badge">${esc(state(b.state))}</span> ${esc(b.username?'@'+b.username:'')}</p>${b.error?`<p>${esc(t(b.error))}</p>`:''}<p>${t(b.configured?'Token 已保存，页面不会回显。':'尚未保存 Token。')}</p><form id="bot-form"><label>Bot Token<input name="token" type="password" autocomplete="new-password" required maxlength="256" ${!owner||active?'disabled':''}></label><p>${t('请只在本机填写 Token。若使用旧模拟版的同一个机器人，先停止模拟机器人。')}</p><div><button ${!owner||active?'disabled':''}>${t('保存 Token')}</button></div></form><div class="actions"><button id="bot-stop" ${!owner||!['running','starting','error'].includes(b.state)?'disabled':''}>${t('停止机器人')}</button><button id="bot-start" class="primary" ${!owner||!b.configured||active?'disabled':''}>${t('启动正式机器人')}</button></div></div>`;}
function startBot(){modal('确认启动正式机器人',`<p>${t('启用后此机器人使用正式商品订单，旧模拟订单不在本入口展示。实际资金功能仍未启用。')}</p><form id="start-bot-form"><label>${t('输入 START')}<input name="confirmation" required pattern="START" autocomplete="off"></label><div class="actions"><button class="primary">${t('启动正式机器人')}</button></div></form>`);$('#start-bot-form').onsubmit=async e=>{e.preventDefault();if(new FormData(e.target).get('confirmation')!=='START')return;const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/bot/start',{});$('#modal').close();toast(t('正式机器人已启动'));await refresh();}catch(e){toast(e.message);button.disabled=false;await refresh();}};}
function modal(title,content){$('#modal-title').textContent=t(title);$('#modal-content').innerHTML=content;$('#modal').showModal();}
async function caseDetail(id){
  const c=data.cases.find(v=>v.id===id),d=await api('/api/orders/'+c.order_id),o=d.order,live=(d.cases??[]).find(v=>v.id===id);
  modal('查看案件',`<div class="details">${[['案件编号',id],['订单编号',o.id],['状态',state(live.status)],['案件说明',live.reason],['买家钱包地址',o.buyer_address],['卖家钱包地址',o.seller_address],['入金总额',amount(o.expected_deposit)],['本金',amount(o.principal)],['手续费',amount(o.fee)]].map(([k,v])=>`<div><span>${t(k)}</span><b class="mono">${esc(v)}</b></div>`).join('')}</div><h2>${t('案件记录')}</h2>${(d.events??[]).filter(e=>e.case_id===id).map(e=>`<p><b>${esc(e.user_id??e.admin_id)}</b> · ${esc(e.action)}<br>${esc(e.message)}</p>`).join('')}<h2>${t('争议附件')}</h2>${(d.files??[]).filter(f=>f.case_id===id).map(f=>`<p><b>${esc(f.user_id)}</b> · ${esc(f.filename)} · ${esc(f.size)} B<br>${esc(f.note)}<br>${f.mime.startsWith('image/')?`<img class="evidence" alt="${esc(f.filename)}" src="/api/case-files/${esc(f.id)}?inline=1"><br>`:''}<a href="/api/case-files/${esc(f.id)}" download>${t('下载附件')}</a> <span class="mono">SHA-256 ${esc(f.sha256)}</span></p>`).join('')||`<p>${t('暂无附件')}</p>`}${live.status==='DISPUTED'&&o.state==='DISPUTED'&&['OWNER','APPROVER'].includes(admin.role)?`<form id="case-resolve-form"><label>${t('裁决方案')}<select name="outcome" required><option value="" disabled selected>${lang==='en'?'Select a decision':'请选择裁决方案'}</option><option value="BUYER">${t('全部退买家（包含手续费）')} · ${amount(o.expected_deposit)}</option><option value="SELLER">${t('本金给卖家（保留原手续费）')} · ${amount(o.principal)}</option></select></label><label>${t('裁决理由')}<textarea name="note" required maxlength="2000"></textarea></label><p>${t('裁决不会直接转账，还需出款审核与独立签名。')}</p><label>${t('输入 RESOLVE')}<input name="confirmation" required pattern="RESOLVE" autocomplete="off"></label><button class="primary">${t('提交裁决并生成待审核出款')}</button></form>`:`<p>${esc(live.resolution_note??'')}</p>`}`);
  $('#case-resolve-form')?.addEventListener('submit',async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(values.confirmation!=='RESOLVE')return;const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/cases/'+id+'/resolve',{...values,revision:o.revision});$('#modal').close();toast(t('案件已提交出款审核'));await refresh();}catch(e){toast(e.message);button.disabled=false;}});
}
