Object.assign(texts.en,{'加密备份与恢复校验':'Encrypted backup and restore check','备份包含正式数据库（订单、账本、出款、案件与附件）和 .env.production（含机器人 Token 与 RPC），使用 AES-256-GCM 与 scrypt 加密，保存在 data/production-backups。创建时会把快照在临时副本中重新打开并校验账本，打不开或不平衡的快照不会保存。平台钱包私钥不在服务器上：请另外保管第4部分下载的平台钱包加密备份和它的密码。':'The backup contains the production database (orders, ledger, payouts, cases and attachments) and .env.production (bot token and RPC), encrypted with AES-256-GCM and scrypt, stored in data/production-backups. The snapshot is reopened in a temporary copy and its ledger checked before saving. The platform wallet keys are not on the server: keep the platform wallet backup from part 4 and its password separately.','备份密码（12至256字符）':'Backup password (12–256 characters)','再次输入备份密码':'Repeat backup password','创建加密备份':'Create encrypted backup','备份已创建':'Backup created','暂无备份':'No backups yet','校验恢复':'Verify restore','输入该备份的密码':'Enter this backup\'s password','开始校验':'Start verification','恢复校验通过':'Restore check passed','恢复副本目录':'Restored copy directory','密码遗失无法恢复。恢复校验只在新目录还原副本，不替换在线数据库。':'A lost password cannot be recovered. Verification restores into a new directory and never replaces the live database.','订单':'Orders','出款交易':'Payout transactions','账目':'Ledger entries','附件':'Attachments','账本平衡':'Ledger balanced','是':'Yes','否':'No','含配置':'Includes config'});
async function backupPanel(){
  const d=await api('/api/backups'),panel=$('#backup-panel');if(!panel)return;
  const row=b=>`<tr><td>${esc(new Date(b.createdAt).toLocaleString())}</td><td>${t('订单')} ${b.summary.orders} · ${t('出款交易')} ${b.summary.payoutTransactions} · ${t('账目')} ${b.summary.ledgerEntries} · ${t('附件')} ${b.summary.caseFiles}</td><td>${(b.bytes/1024).toFixed(0)} KB${b.configurationIncluded?' · '+t('含配置'):''}</td><td><button data-verify="${esc(b.id)}">${t('校验恢复')}</button></td></tr>`;
  panel.innerHTML=`<h2>${t('加密备份与恢复校验')}</h2><p>${t('备份包含正式数据库（订单、账本、出款、案件与附件）和 .env.production（含机器人 Token 与 RPC），使用 AES-256-GCM 与 scrypt 加密，保存在 data/production-backups。创建时会把快照在临时副本中重新打开并校验账本，打不开或不平衡的快照不会保存。平台钱包私钥不在服务器上：请另外保管第4部分下载的平台钱包加密备份和它的密码。')}</p><p>${t('密码遗失无法恢复。恢复校验只在新目录还原副本，不替换在线数据库。')}</p>
  <form id="backup-form"><label>${t('备份密码（12至256字符）')}<input name="password" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label><label>${t('再次输入备份密码')}<input name="repeat" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label><div class="actions"><button class="primary">${t('创建加密备份')}</button></div></form>
  ${d.backups.length?`<table><tbody>${d.backups.map(row).join('')}</tbody></table>`:`<p>${t('暂无备份')}</p>`}`;
  $('#backup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;try{await api('/api/backups',{password:f.get('password'),repeat:f.get('repeat')});e.target.reset();toast(t('备份已创建'));await backupPanel();}catch(e){toast(e.message);}finally{button.disabled=false;}};
  for(const button of panel.querySelectorAll('[data-verify]'))button.onclick=()=>{modal('校验恢复',`<form id="verify-form"><label>${t('输入该备份的密码')}<input name="password" type="password" minlength="12" maxlength="256" required autocomplete="off"></label><div class="actions"><button class="primary">${t('开始校验')}</button></div></form><div id="verify-result"></div>`);
    $('#verify-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api('/api/backups/'+button.dataset.verify+'/verify',{password:new FormData(e.target).get('password')});e.target.reset();$('#verify-result').innerHTML=`<p><b>${t('恢复校验通过')}</b></p><div class="details"><div><span>${t('恢复副本目录')}</span><b class="mono">${esc(r.directory)}</b></div><div><span>${t('订单')}</span><b>${r.summary.orders}</b></div><div><span>${t('账目')}</span><b>${r.summary.ledgerEntries}</b></div><div><span>${t('附件')}</span><b>${r.summary.caseFiles}</b></div><div><span>${t('账本平衡')}</span><b>${t(r.summary.balanced?'是':'否')}</b></div></div>`;}catch(e){toast(e.message);}finally{b.disabled=false;}};};
}
