async function automationPanel(){
  const d=await api('/api/automation'),panel=$('#automation-panel');if(!panel)return;
  const yes=(v,a,b)=>`<b>${t(v?a:b)}</b>`;
  panel.innerHTML=`<h2>🤖 ${t('自动出款')}</h2><p>${t('开启后，买家放款、退款、仲裁结果和超时退款会自动审核、签名并广播，无需人工操作。钱包私钥只在内存中，后台重启后需要重新解锁。')}</p>
  <div class="details"><div><span>${t('状态')}</span>${yes(d.enabled,'已开启','已关闭')}</div><div><span>${t('钱包')}</span>${yes(d.unlocked,'已解锁','未解锁')}</div><div><span>${t('入金监听')}</span>${yes(d.monitoring,'运行中','未运行')}</div>${d.pausedReason?`<div><span>${t('自动暂停原因')}</span><b>${esc(d.pausedReason)}</b></div>`:''}${d.lastError?`<div><span>${t('最近错误')}</span><b>${esc(d.lastError)}</b></div>`:''}</div>
  ${d.unlocked?`<div class="actions"><button id="auto-lock">${t('锁定钱包（清除内存中的私钥）')}</button></div>`:`<form id="unlock-form"><label>${t('选择平台钱包加密备份')}<input name="backup" type="file" accept=".json,application/json" required></label><label>${t('备份密码')}<input name="password" type="password" autocomplete="off" required maxlength="256"></label><div class="actions"><button class="primary">${t('解锁钱包')}</button></div></form>`}
  <div class="actions">${d.enabled?`<button id="auto-off" class="danger">${t('关闭自动出款')}</button>`:`<button id="auto-on" class="primary">${t('开启自动出款')}</button>`}</div>`;
  $('#unlock-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,file=f.elements.backup.files[0],button=f.querySelector('button');if(!file||file.size>32768)return toast(t('选择平台钱包加密备份'));button.disabled=true;
    try{await api('/api/automation/unlock',{backup:await file.text(),password:f.elements.password.value});f.elements.password.value='';toast(t('钱包已解锁'));await automationPanel();}catch(err){f.elements.password.value='';toast(err.message);button.disabled=false;}});
  $('#auto-lock')?.addEventListener('click',async()=>{try{await api('/api/automation/lock',{});toast(t('钱包已锁定'));await automationPanel();}catch(err){toast(err.message);}});
  $('#auto-off')?.addEventListener('click',async()=>{try{await api('/api/automation/enable',{enabled:false});await automationPanel();}catch(err){toast(err.message);}});
  $('#auto-on')?.addEventListener('click',async()=>{const word=prompt(t('开启后资金会自动转出且无法撤回。输入 AUTO 确认：'));if(word===null)return;try{await api('/api/automation/enable',{enabled:true,confirmation:word});await automationPanel();}catch(err){toast(err.message);}});
}
