async function custodyPanel(){
  const panel=$('#custody-panel');if(!panel)return;const d=await api('/api/custody'),owner=admin.role==='OWNER';
  const kinds={RELEASE:t('放款给卖家'),REFUND:t('退款给买家'),MANUAL_REFUND:t('人工退回买家'),ARBITRATION:t('仲裁出款')},labels={UNCLAIMED:t('无法识别的入金'),CLAIM_PENDING:t('买家认领待确认'),UNMATCHED:t('未匹配的转出')};
  const amount=v=>{const n=BigInt(v),f=(n%10n**18n).toString().padStart(18,'0').replace(/0+$/,'');return (n/10n**18n).toString()+(f?'.'+f:'');};
  panel.innerHTML=`<h2>${t('🏦 固定托管地址（人工出款）')}</h2><p>${t('设置后，新的群订单都显示这个地址作为托管地址，入金按买家声明的地址自动识别。平台没有这个地址的私钥：放款和退款需要你从这个地址手动转账，系统看到转出的金额和收款地址一致后自动完成订单。')}</p>
  <p>${t('当前固定托管地址：')}<b class="mono">${d.address?esc(d.address):t('未设置（使用平台生成的地址）')}</b>${d.scannedAt?` · ${t('最近扫描：')}${esc(new Date(d.scannedAt).toLocaleString())}`:''}</p>
  ${owner?`<form id="custody-form"><label>${t('你的钱包地址（留空则清除）')}<input name="address" class="mono" maxlength="42" pattern="0x[0-9a-fA-F]{40}" value="${esc(d.address??'')}" autocomplete="off"></label><div class="actions"><button class="primary">${t('保存固定托管地址')}</button></div></form>`:''}
  <h3>${t('待你手动转账')}</h3><p>${t('请一次性转出准确金额，到收款地址；系统自动完成订单。')}</p>
  ${d.payouts.length?`<table><tbody>${d.payouts.map(r=>`<tr><td>${esc(r.order_id.slice(0,8).toUpperCase())}</td><td>${esc(kinds[r.kind]??r.kind)}</td><td>${t('转账金额')} <b>${esc(amount(r.allocations[0].amount))} USDT</b></td><td>${t('收款地址')} <span class="mono">${esc(r.allocations[0].recipient)}</span></td></tr>`).join('')}</tbody></table>`:`<p>${t('暂无')}</p>`}
  <h3>${t('需要处理的入金与转出')}</h3>
  ${d.transfers.length?`<table><tbody>${d.transfers.map(x=>`<tr><td>${esc(labels[x.status]??x.status)}</td><td><b>${esc(amount(x.amount))} USDT</b></td><td class="mono">${esc(x.counterparty)}</td><td class="mono">${esc(x.tx_hash.slice(0,18))}…</td><td>${x.direction==='IN'?`<input data-order="${esc(x.id)}" placeholder="${t('订单编号（完整）')}" value="${esc(x.order_id??'')}" size="38"><button data-assign="${esc(x.id)}">${t('记入订单')}</button><button data-ignore="${esc(x.id)}">${t('忽略')}</button>`:''}</td></tr>`).join('')}</tbody></table>`:`<p>${t('暂无')}</p>`}`;
  $('#custody-form')?.addEventListener('submit',async e=>{e.preventDefault();const address=e.target.elements.address.value.trim();if(address&&!confirm(`${t('确认把新群订单的托管地址设为：')}\n${address}`))return;try{await api('/api/custody/address',{address});toast(t('已保存固定托管地址'));await refresh();}catch(err){toast(err.message);}});
  for(const b of panel.querySelectorAll('[data-assign]'))b.onclick=async()=>{const orderId=panel.querySelector(`[data-order="${b.dataset.assign}"]`).value.trim();try{await api(`/api/custody/transfers/${b.dataset.assign}/assign`,{orderId});await custodyPanel();}catch(err){toast(err.message);}};
  for(const b of panel.querySelectorAll('[data-ignore]'))b.onclick=async()=>{if(!confirm(t('确认忽略这笔入金？')))return;try{await api(`/api/custody/transfers/${b.dataset.ignore}/ignore`,{});await custodyPanel();}catch(err){toast(err.message);}};
}
